inline std::string encode(const Registration& v) {
    std::string out;
    detail::enc_registration(out, v, 0);
    out += '\n';
    return out;
}

inline Registration decode(std::string_view data) {
    detail::Reader r{data};
    r.skip_ws();
    Registration v = detail::decode_registration(r);
    r.skip_ws();
    if (r.pos < r.buf.size()) r.refuse("trailing_bytes");
    return v;
}

